From 1b3f22c9a6c78499b69019a81eb528a160886844 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:51:02 +0100
Subject: [PATCH] shell/panelview: hide auto-hide panel again after the user
 looked at it

An auto-hide panel shown because a task demands attention stayed visible
until the attention was cleared. Now it hides once the pointer leaves
it, and only shows again when a new attention request arrives.

BUG: 435095
---
 shell/panelview.cpp | 9 ++++++++-
 shell/panelview.h   | 1 +
 2 files changed, 9 insertions(+), 1 deletion(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..8650a388d7 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -964,7 +964,8 @@ void PanelView::restoreAutoHide()
         autoHide = false;
     } else if (m_corona->isEditMode()) {
         autoHide = false;
-    } else if (containment() && containment()->status() >= Plasma::Types::NeedsAttentionStatus && containment()->status() != Plasma::Types::HiddenStatus) {
+    } else if (containment() && containment()->status() >= Plasma::Types::NeedsAttentionStatus && containment()->status() != Plasma::Types::HiddenStatus
+               && !(containment()->status() == Plasma::Types::NeedsAttentionStatus && m_attentionDismissed)) {
         autoHide = false;
     } else {
         for (QWindow *window : qApp->topLevelWindows()) {
@@ -1182,6 +1183,10 @@ bool PanelView::event(QEvent *e)

     case QEvent::Leave:
         m_containsMouse = false;
+        if (containment() && containment()->status() == Plasma::Types::NeedsAttentionStatus) {
+            // BUG 435095: once the user has looked at the panel, let it hide again
+            m_attentionDismissed = true;
+        }
         if (edgeActivated()) {
             m_unhideTimer.start();
         }
@@ -1586,6 +1591,8 @@ void PanelView::handleQmlStatusChange(QQmlComponent::Status status)

 void PanelView::refreshStatus(Plasma::Types::ItemStatus status)
 {
+    m_attentionDismissed = false;
+
     if (status == Plasma::Types::NeedsAttentionStatus) {
         showTemporarily();
         setFlags(flags() | Qt::WindowDoesNotAcceptFocus);
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..aa7fa76228 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -348,6 +348,7 @@ private:
     bool m_floatingApplets;
     bool m_containsMouse = false;
     bool m_containsDrag = false;
+    bool m_attentionDismissed = false;
     bool m_fakeEventPending = false;
     bool m_touchingWindow = false;
     Qt::Alignment m_alignment;
